package com.skillpulse.personalization;
import javax.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="personalized_plan_days",uniqueConstraints=@UniqueConstraint(columnNames={"plan_id","day_number"})) public class PersonalizedPlanDay {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="plan_id") private PersonalizedPlan plan; @Column(name="day_number",nullable=false) private int dayNumber; @Column(nullable=false) private LocalDate targetDate; @Column(nullable=false,length=500) private String focus; @Column(length=1200) private String objective; @Column(nullable=false) private int plannedMinutes; @Column(nullable=false) private boolean completed; private Instant completedAt;
 @OneToMany(mappedBy="planDay",cascade=CascadeType.ALL,orphanRemoval=true) private List<PersonalizedPlanTask> tasks=new ArrayList<PersonalizedPlanTask>();
 public Long getId(){return id;} public PersonalizedPlan getPlan(){return plan;} public void setPlan(PersonalizedPlan v){plan=v;} public int getDayNumber(){return dayNumber;} public void setDayNumber(int v){dayNumber=v;} public LocalDate getTargetDate(){return targetDate;} public void setTargetDate(LocalDate v){targetDate=v;} public String getFocus(){return focus;} public void setFocus(String v){focus=v;} public String getObjective(){return objective;} public void setObjective(String v){objective=v;} public int getPlannedMinutes(){return plannedMinutes;} public void setPlannedMinutes(int v){plannedMinutes=v;} public boolean isCompleted(){return completed;} public void setCompleted(boolean v){completed=v;} public void setCompletedAt(Instant v){completedAt=v;} public List<PersonalizedPlanTask> getTasks(){return tasks;}
}
